		t.Run(tc.description, func(t *testing.T) {
			if actual, err := SquareRoot(tc.input); err != nil {
				t.Fatalf("SquareRoot(%d) returned error: %d, want: %d", tc.input, err, tc.expected)
			} else if actual != tc.expected {
